import os
import re
import json

d = os.environ['RLM_SESSION_DIR']
content = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

# Parse as JSON lines
lines = content.split('\n')
found_grids = {}

for line in lines:
    if not line.strip():
        continue
    try:
        msg = json.loads(line)
        grid_key = None
        for k in ['grid_key', 'input_grid_key', 'output_grid_key', 'grid']:
            if k in msg:
                grid_key = k
        if grid_key:
            found_grids[grid_key] = msg[grid_key]
    except:
        pass

# Let me search differently - look for patterns in the text
text = content.lower()
if 'demo pair 1 input' in text:
    print("Found demo pair 1 input")
    # Search for the location
    mi = re.search(r'Demo pair \d+(?: input|output) \(\d+x\d+\):', text)
    if mi:
        print(f"Found at position: {mi.start()}")
        context = text[mi.start()-50:mi.end()+500]
        print(f"Context:\n{context[:1000]}")
